<script>
  import { storeToRefs } from "pinia";  
  import { useloggedUserInfo} from "./stores/NavUserInfo";
  import { subscribeUser } from '../src/components/common/pushUtils';
  const currentUrl = window.location.pathname;
  const defaultAppUrl = process.env.VUE_APP_DEFAULT_APP_URL;
  const vapidKey = process.env.VUE_APP_VAPID_PUBLIC_KEY
export default {
  data: function(){
    return {
      currentUrlVue : currentUrl
    }
  },
    mounted() {
    this.handleSubscription();
  },
  methods: {
    async handleSubscription() {
      const subscription = await subscribeUser(vapidKey);
      if (subscription) {
        this.subscription = JSON.stringify(subscription, null, 2);
      }
    }
  },
  setup(){     
    
    const store = useloggedUserInfo();
		const { GetUserInfo } = storeToRefs(store)
    store.setBillingType();
    store.setindustryType();
    setTimeout(() => {      
      // $("#divProgress1").css('display','none')
      // $("#talygenfooter").css('display','block')
      if(window.location.pathname=='/' && GetUserInfo.value.UserType != "CL"){
        window.location.href = '/User/Dashboard';
      } else if(GetUserInfo.value.UserType == "CL" && (currentUrl.toString().toLowerCase() == '/user/dashboard' || window.location.pathname=='/' || currentUrl.toString().toLowerCase() == '/user/home') ) {
        window.location.href = '/Client/dashboard';
      }
    }, 1000);
		return {GetUserInfo }
  }, 
}
</script>
<template>
    <section>
        <TALYGENHeader v-if="GetUserInfo != null && currentUrlVue.toString().toLowerCase() != '/Communication/Index'.toLowerCase() && currentUrlVue.toString().toLowerCase() != '/company/initialsetup'.toLowerCase() && currentUrlVue.toString().toLowerCase() != '/client/activateclient'.toLowerCase()" />
    </section>    
</template>
