                                            </span>
                                            <span v-if="getParsedField(result, 'sba_name')" class="work-item-meta-item">
                                                <span class="meta-label">SBA:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'sba_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_name')" class="work-item-meta-item">
                                                <span class="meta-label">Division:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_description')" class="work-item-meta-item">
                                                <span class="meta-label">Division Description:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_description'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">Status:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isUtilityResult(result)">
                                            <span v-if="getParsedField(result, 'email_id')" class="work-item-meta-item">
                                                <span class="meta-label">Email:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'email_id'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">Contract Name:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'sba_name')" class="work-item-meta-item">
                                                <span class="meta-label">SBA:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'sba_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_name')" class="work-item-meta-item">
                                                <span class="meta-label">Division:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'division_description')" class="work-item-meta-item">
                                                <span class="meta-label">Division Description:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'division_description'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">Status:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else-if="isTicketResult(result)">
                                            <!-- <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">Contract:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'user_name')" class="work-item-meta-item">
                                                <span class="meta-label">Client:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'user_name'), searchQuery)"></span>
                                            </span> -->
                                            <span v-if="getParsedField(result, 'created_at')" class="work-item-meta-item">
                                                <span class="meta-label">Created At:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'created_at'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'priority_id')" class="work-item-meta-item">
                                                <span class="meta-label">Priority:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'priority_id'), searchQuery)"></span>
                                            </span>
                                              <span v-if="getParsedField(result, 'contract_name')" class="work-item-meta-item">
                                                <span class="meta-label">Contract:</span>
                                                <span class="meta-value" v-html="highlightText(getParsedField(result, 'contract_name'), searchQuery)"></span>
                                            </span>
                                            <span v-if="getParsedField(result, 'status_name')" class="work-item-meta-item">
                                                <span class="meta-label">Status:</span>
                                                <span class="meta-value status-value" :class="getStatusClass(getParsedField(result, 'status_name'))">{{ getParsedField(result, 'status_name') }}</span>
                                            </span>
                                        </template>
                                        <template v-else>
                                            <span class="work-item-project">{{ result.type || result.project || 'Result' }}</span>
                                            <span class="work-item-separator" v-if="result.subtitle">•</span>
                                            <span class="work-item-type" v-if="result.subtitle">{{ result.subtitle }}</span>
                                        </template>



                                        <!-- <span class="work-item-title">{"ticket_number":"2529611156","description":"Paint and Flag",
                                            "contract_name":"AT&amp;T - Tennessee (10001274)","city":"<mark>TELICO</mark> PLAINS",
                                            "status":"PROCESSED","work_date":"2025-10-28T07:03:00","ticket_type":"NORMAL NOTICE       ",
                                            "utility_name":"AT&amp;T","activity_id":1756321432,"is_mannual":false,"cost_center":5201,
                                            "bill_number":"INV420332"}</span> -->
                                </div>
                            </div>
                            </div>
                        </div>
                        <!-- View All Results Link -->
                        <div v-if="totalCount > maxResults" class="view-all-results-footer">
                            <a id="viewAllResults" :href="viewAllResultsHref" @click="viewAllResults" class="view-all-link">
                                View All Results ({{ totalCount }}+) <em class="fa fa-arrow-right ml-1"></em>
                            </a>
                    </div>
                    
                    </div>
                    </div>
            </div>
            </transition>

        </div>
