</template>

<script>
import DataService from "../../services/DataService";

export default {
    name: 'GlobalSearch',
    data() {
        return {
            searchQuery: '',
            searchResults: [],
            showResults: false,
            isSearching: false,
            minSearchLength: 2,
            maxResults: 10, // Show 5 in dropdown, rest in detail page
            searchDebounceTimer: null,
            searchDebounceDelay: 2000, // 2 seconds delay before API call
            selectedIndex: -1,
            totalCount: 0,
            availableModules: [],
            moduleListData: [], // Store full module objects from API
            selectedModules: [],
            showModulesDropdown: false,
            moduleSearchQuery: '',
            filteredModules: [],
            activeTab: 'recent',
            showSearchOverlay: false,
            recentSearches: [],
            recentWorkItems: [],
            searchSuggestions: [
                { query: 'Q Show all the bugs assigned to me', label: 'Suggestion' },
                { query: 'Q Recent open items assigned to Mason', label: 'Suggestion' }
            ],
            selectedModule: '',
            userTypeId:1,
        }
    },
    computed: {
        displayResults() {
            debugger
            // Filter by selected modules if any
            if (this.selectedModules.length > 0) {
                // Expand the selected module(s) into entity types for filtering.
                // For `Billing`, we need to show both entities: `Talygen_bill` and `TALYGEN_BE_client_configuration`.
                var entityTypes = [];
                this.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        entityTypes.push('Talygen_bill');
                        entityTypes.push('TALYGEN_BE_client_configuration');
                    } else {
                        var mapped = this.getEntityTypeFromModuleName(m);
                        if (mapped) {
                            entityTypes.push(mapped);
                        }
                    }
                });
                entityTypes = entityTypes.map(t => t.toLowerCase());
                return this.searchResults.filter(r => 
                    entityTypes.includes(r.type.toLowerCase())
                );
            }
            return this.searchResults;
        },
        displayRecentItems() {
            // Show recent work items or search results
            if (this.searchQuery.length >= this.minSearchLength && this.searchResults.length > 0) {
                return this.searchResults.slice(0, 10);
            }
            return this.recentWorkItems.slice(0, 10);
        },
        viewAllResultsHref() {
            var vm = this;
            var queryParams = { q: vm.searchQuery };
            if (vm.selectedModules.length > 0) {
                // Expand Billing to both entity types so the results page also returns both.
                var modulesExpanded = [];
                vm.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        modulesExpanded.push('Talygen_bill');
                        modulesExpanded.push('TALYGEN_BE_client_configuration');
                    } else {
                        modulesExpanded.push(m);
                    }
                });
                queryParams.modules = modulesExpanded.join(',');
            }
            
            if (vm.$router) {
                try {
                    var resolved = vm.$router.resolve({ path: '/Search/Results', query: queryParams });
                    return resolved.href;
                } catch (e) {
                    // Fallback to manual URL building if router resolve fails
                    var queryString = Object.keys(queryParams).map(key => 
                        key + '=' + encodeURIComponent(queryParams[key])
                    ).join('&');
                    return `/Search/Results?${queryString}`;
                }
            } else {
                // Fallback if router not available
                var queryString = Object.keys(queryParams).map(key => 
                    key + '=' + encodeURIComponent(queryParams[key])
                ).join('&');
                return `/Search/Results?${queryString}`;
            }
        }
    },
    created() {
        this.userTypeId = this.GetUserInfo.UserType == 'CA' ? 1 : this.GetUserInfo.UserType == 'PM' ? 2 : this.GetUserInfo.UserType == 'NU' ? 3 : 4;
        this.loadAvailableModules();
        this.loadRecentSearches();
        //this.loadRecentWorkItems();
    },
    methods: {
        onSearchInput(event) {
            var vm = this;
            // Allow spaces - don't trim the input value, only trim when sending to API
            var query = event.target.value;
            vm.searchQuery = query;
            
            // Clear previous timer
            if (vm.searchDebounceTimer) {
                clearTimeout(vm.searchDebounceTimer);
            }
            
            // Reset selected index
            vm.selectedIndex = -1;
            
            // If query is too short (after trimming), clear results but keep overlay open
            var trimmedQuery = query.trim();
            if (trimmedQuery.length < vm.minSearchLength) {
                vm.searchResults = [];
                vm.isSearching = false;
                // Don't return early - keep overlay open for user to continue typing
            } else {
                // Only show loading state when we're about to search (after debounce)
                // Don't set isSearching = true immediately to avoid showing loading while typing
            }
            
            // Debounce the search - only call API after user stops typing for 2 seconds
            vm.searchDebounceTimer = setTimeout(function() {
                // Trim query only when sending to API
                var finalQuery = trimmedQuery;
                if (finalQuery.length >= vm.minSearchLength) {
                    vm.isSearching = true;
                    vm.performGlobalSearch(finalQuery);
                } else {
                    vm.isSearching = false;
                    vm.searchResults = [];
                }
            }, vm.searchDebounceDelay);
        },
        
        performGlobalSearch(query) {
            var vm = this;
            
            // Trim query for API call but allow spaces in input
            var trimmedQuery = query ? query.trim() : '';
            
            // Validate query length
            if (!trimmedQuery || trimmedQuery.length < vm.minSearchLength) {
                vm.searchResults = [];
                vm.totalCount = 0;
                vm.isSearching = false;
                return;
            }
            
            vm.isSearching = true;
            
            // Build modules parameter if any selected
            var modulesParam = '';
            if (vm.selectedModules.length > 0) {
                // Expand Billing to both entity types so the server returns both.
                var modulesExpanded = [];
                vm.selectedModules.forEach(m => {
                    var moduleLower = (m || '').toString().toLowerCase().trim();
                    if (moduleLower === 'billing') {
                        modulesExpanded.push('Talygen_bill');
                        modulesExpanded.push('TALYGEN_BE_client_configuration');
                    } else {
                        modulesExpanded.push(m);
                    }
                });
                modulesParam = `&modules=${encodeURIComponent(vm.selectedModules.join(','))}&entityType=${encodeURIComponent(modulesExpanded.join(','))}`;
            }
            
            var url = `searchQuery=${encodeURIComponent(trimmedQuery)}&pageNumber=1&pageSize=${vm.maxResults}${modulesParam}`;
            
            console.log('Global Search API Call:', url);
            
            DataService.GlobalSearch(url).then(function(response) {
                vm.isSearching = false;
                console.log('Global Search Response:', response);
                
                if (response && response.data) {
                    // Check if response has results array
                    var results = [];
                    if (Array.isArray(response.data.results)) {
                        results = response.data.results;
                    } else if (response.data.results && typeof response.data.results === 'object') {
                        // If results is an object, try to extract array
                        results = [];
                        console.warn('Results is not an array:', response.data.results);
                    }
                    
                    vm.searchResults = results;
                    
                    // Use totalCount from API response
                    var apiTotalCount = response.data.totalCount || 0;
                    vm.totalCount = apiTotalCount > 0 ? apiTotalCount : (results.length > 0 ? results.length : 0);
                 //   debugger
                    // // Update module counts if available
                    // if (response.data.moduleCounts) {
                    //     // Extract available modules from moduleCounts
                    //     vm.availableModules = Object.keys(response.data.moduleCounts);
                       
                    // }
                    // vm.availableModules.forEach(item => {
                    //     if(item.text=="Client Bill"){
                    //        item.value="Talyegn_bill"
                    //     }
                    //      if(item.text=="Clients"){
                    //        item.value="Talyegn_user"
