        positionOverlay() {
            var vm = this;
            if (vm.$refs.searchInput && vm.$refs.searchOverlay) {
                var searchInput = vm.$refs.searchInput;
                var overlay = vm.$refs.searchOverlay;
                var content = overlay.querySelector('.search-overlay-content');
                
                if (content && searchInput) {
                    var rect = searchInput.getBoundingClientRect();
                    
                    // Position content below the search input
                    var topPosition = rect.bottom + 2;
                    // Align to left edge of the search textbox
                    var leftPosition = rect.left;
                    var contentWidth = Math.max(rect.width, 600);
                    
                    // Ensure content doesn't go off screen
                    if (leftPosition + contentWidth > window.innerWidth) {
                        leftPosition = window.innerWidth - contentWidth - 20;
                    }
                    if (leftPosition < 20) {
                        leftPosition = 20;
                    }
                    
                    content.style.top = topPosition + 'px';
                    content.style.left = leftPosition + 'px';
                    content.style.width = Math.min(contentWidth, 800) + 'px';
                    content.style.maxWidth = '800px';
                    content.style.transform = 'none';
                }
            }
        },
        
        handleSearchBlur(event) {
            var vm = this;
            // Don't close overlay on blur if clicking inside overlay
            setTimeout(function() {
                var activeElement = document.activeElement;
                var overlay = vm.$refs.searchOverlay;
                var overlayContent = overlay ? overlay.querySelector('.search-overlay-content') : null;
                
                // Check if focus moved to overlay content or if overlay should stay open
                if (overlayContent && overlayContent.contains(activeElement)) {
                    return; // Don't close if focus is in overlay
                }
                
                // Don't close overlay if it's still supposed to be open (e.g., after selecting recent)
                if (vm.showSearchOverlay && vm.searchQuery && vm.searchQuery.trim().length >= vm.minSearchLength) {
                    // Keep overlay open if we have search results or are searching
                    if (vm.isSearching || vm.searchResults.length > 0) {
                        // Refocus input to keep overlay open
                        if (vm.$refs.searchInput) {
                            vm.$refs.searchInput.focus();
                        }
                        return;
                    }
                }
                
                // Only handle overlay, no old dropdown
                if (!vm.showSearchOverlay) {
                    if (!overlayContent || !overlayContent.contains(activeElement)) {
                        vm.showModulesDropdown = false;
                    }
                }
            }, 200);
        },
        
        onEnterKey() {
