            if (vm.selectedIndex >= 0 && vm.selectedIndex < vm.displayResults.length) {
                vm.onSearchResultClick(vm.displayResults[vm.selectedIndex]);
            } else if (vm.displayResults.length > 0) {
                vm.onSearchResultClick(vm.displayResults[0]);
