        viewAllResults(event) {
            var vm = this;
            
            // Check if we're already on the same route with same query params
            if (vm.$router && vm.$route) {
                var queryParams = { q: vm.searchQuery };
                if (vm.selectedModules.length > 0) {
                    queryParams.modules = vm.selectedModules.join(',');
                }
                
                var currentRoute = vm.$route;
                var isSameRoute = currentRoute.path === '/Search/Results' && 
                                 currentRoute.query.q === queryParams.q &&
                                 (currentRoute.query.modules || '') === (queryParams.modules || '');
                
                if (isSameRoute) {
                    // Already on the same route, prevent navigation and just close overlay
                    event.preventDefault();
                    vm.closeSearchOverlay();
                    return;
                }
                
                // Try to navigate using router, catch NavigationDuplicated errors
                try {
                    vm.$router.push({ path: '/Search/Results', query: queryParams }).catch(function(err) {
                        // Ignore NavigationDuplicated errors (user clicked same link twice)
                        if (err.name !== 'NavigationDuplicated') {
                            console.error('Navigation error:', err);
                        }
                    });
                } catch (e) {
                    // If router push fails, let the href handle navigation
                    console.warn('Router navigation failed, using href:', e);
                }
            }
            
            // Close overlay after navigation
            vm.closeSearchOverlay();
        },
        
        clearSearch() {
            var vm = this;
            vm.searchQuery = '';
            vm.searchResults = [];
            vm.showSearchOverlay = false;
            vm.selectedIndex = -1;
            vm.totalCount = 0;
            vm.showModulesDropdown = false;
            
            // Re-enable body scroll
            document.body.style.overflow = '';
            
            if (vm.searchDebounceTimer) {
                clearTimeout(vm.searchDebounceTimer);
                vm.searchDebounceTimer = null;
