        highlightText(text, query) {
            if (!text || !query) {
                return text || '';
            }
            
            // Ensure text is a string before calling replace
            var textStr = String(text);
            var regex = new RegExp('(' + this.escapeRegex(query) + ')', 'gi');
            return textStr.replace(regex, '<mark>$1</mark>');
        },
        
        escapeRegex(string) {
            return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        },
        
        formatDate(date) {
            if (!date) return '';
            try {
                var d = new Date(date);
                if (isNaN(d.getTime())) return date;
                var month = (d.getMonth() + 1).toString().padStart(2, '0');
                var day = d.getDate().toString().padStart(2, '0');
                var year = d.getFullYear();
                return month + '/' + day + '/' + year;
            } catch (e) {
                return date;
            }
        },
        
        formatCurrency(amount) {
            if (!amount && amount !== 0) return '';
            try {
                return parseFloat(amount).toLocaleString('en-US', {
                    style: 'currency',
                    currency: 'USD',
                    minimumFractionDigits: 2
                });
            } catch (e) {
                return amount;
            }
        },

        parseDisplayText(result) {
            // Try to parse display_text as JSON
            if (!result.title) {
                return null;
            }
            
            try {
                var title = result.title.trim();
                // Check if title is JSON string (may be truncated with ...)
                if (title.startsWith('{')) {
                    // Handle truncated JSON (ends with ...)
                    if (title.endsWith('...')) {
                        title = title.replace(/\.\.\.$/, '');
                        // Try to close the JSON object
                        if (!title.endsWith('}')) {
                            title += '}';
                        }
                    }
                    // Ensure it ends with }
                    if (!title.endsWith('}')) {
                        title += '}';
                    }
                    return JSON.parse(title);
                }
            } catch (e) {
                // Not valid JSON, return null
                console.debug('Failed to parse JSON:', e);
            }
            
            return null;
        },

        getParsedField(result, fieldName) {
            var parsed = this.parseDisplayText(result);
            if (parsed && parsed[fieldName]) {
                return parsed[fieldName];
            }
            return null;
        },

        isInvoiceResult(result) {
            return result.type === 'Invoice' || result.type === 'Talygen_bill' || 
                   (result.type && result.type.toLowerCase().includes('bill'));
        },
        isBillingRuleResult(result) {
            return result.type === 'BillingRule' || result.type === 'TALYGEN_BE_client_configuration' || 
                   (result.type && result.type.toLowerCase().includes('BillingRule'));
        },

        isUserResult(result) {
            return result.type === 'Talygen_user' || result.type === 'User' ||
                   (result.type && result.type.toLowerCase().includes('user'));
        },
        isContractResult(result) {
            return result.type === 'Talygen_company_client' || result.type === 'Contract' ||
                   (result.type && result.type.toLowerCase().includes('contract'));
        },

        isCdcCodeResult(result) {
            return result.type === 'TALYGEN_BE_cdc_code_info'   ||  result.type === 'cdc_code' || 
                   (result.type && (result.type.toLowerCase().includes('cdc_code') || result.type.toLowerCase().includes('cdc')));
        },
        isUtilityResult(result) {
            return result.type === 'TALYGEN_client_additional_info' ||  result.type === 'Utility' ||
                   (result.type && (result.type.toLowerCase().includes('Utility_name') || result.type.toLowerCase().includes('utility')));
        },
        isTicketResult(result) {
            return result.type === 'Talygen_ticket' || result.type === 'Talygen_Ticket' || 
                   (result.type && result.type.toLowerCase().includes('ticket'));
        },

        getResultIcon(result) {
            // Check if result has icon property first
            if (result.icon) {
                return result.icon;
            }
            if (result.Icon) {
                return result.Icon;
            }
            
            // Determine icon based on result type
            if (this.isInvoiceResult(result)) {
                return 'file-text-o';
            }
            if (this.isBillingRuleResult(result)) {
                return 'gear';
            }
            
            if (this.isUserResult(result)) {
                return 'user';
            }
            if (this.isCdcCodeResult(result)) {
                return 'code';
            }
            if (this.isUtilityResult(result)) {
                return 'globe';
            }
            return 'circle';
        },

        getResultId(result) {
            var parsed = this.parseDisplayText(result);
            // For invoices, extract invoice_no from JSON
            if (this.isInvoiceResult(result)) {
                if (parsed && parsed.invoice_no) {
                    return parsed.invoice_no;
                }
            }
            if (this.isBillingRuleResult(result)) {
                if (parsed && parsed.billing_rule_name) {
                    return parsed.billing_rule_name;
                }
            }
            
            // For users, show user_id from JSON
            if (this.isUserResult(result)) {
                if (parsed && parsed.email_id) {
                    return parsed.email_id;
                }
            }
            if (this.isContractResult(result)) {
                if (parsed && parsed.contract_name!='') {
                    return parsed.contract_name;
                }
                if (parsed && parsed.user_name!='') {
                    return parsed.user_name;
                }
            }
            
            // For CDC Code, show utility_name from JSON
            if (this.isCdcCodeResult(result)) {
                if (parsed) {
                    if (parsed.cdc_code && parsed.cdc_code) {
                        return parsed.cdc_code;
                    }
                }
                // Fallback to ID if utility_name not found
                return result.id || 'cdc_code';
            }
             if (this.isUtilityResult(result)) {
                if (parsed) {
                    if (parsed.utility_name && parsed.utility_name) {
                        return parsed.utility_name;
                    }
                }
                // Fallback to ID if utility_name not found
                return result.id || 'Utility';
            }

            
            if (this.isTicketResult(result)) {
                if (parsed && parsed.ticket_number) {
                    return parsed.ticket_number;
                }
            }
            
            // Default: return ID or first part of title
            return result.id || (result.title ? result.title.split(/\s+/)[0] : null);
        },

        getResultDescription(result) {

            var parsed = this.parseDisplayText(result);
            
            // For invoices, get contract_name or user_name from JSON
            if (this.isInvoiceResult(result)) {
                if (parsed) {
                    if (parsed.contract_name) {
                        return parsed.contract_name;
                    }
                    if (parsed.user_name) {
                        return parsed.user_name;
                    }
                }
            }

            if (this.isBillingRuleResult(result)) {
                if (parsed) {
                    if (parsed.contract_name) {
                        return parsed.contract_name;
                    }
                }
            }
            
            
            // For users, show user_name or contract_name from JSON
            if (this.isUserResult(result)) {
                if (parsed) {
                    if (parsed.user_name) {
                        return parsed.user_name;
                    }
                }
            }
            if (this.isContractResult(result)) {
                if (parsed) {
                    if (parsed.email_id) {
                        return parsed.email_id;
                    }
                }
            }
            
            // For CDC Code, show contract_name or user_name from JSON
            if (this.isCdcCodeResult(result)) {
                if (parsed) {
                    if (parsed.utility_name) {
                        return parsed.utility_name;
                    }
                }
            }
            if (this.isUtilityResult(result)) {
                if (parsed) {
