                        return parsed.utility_desc;
                    }
                    else if (parsed.utility_name) {
                        return '';
                    }
                }
            }
            if (this.isTicketResult(result)) {
                if (parsed) {
                    if (parsed.ticket_subject) {
                        return parsed.ticket_subject;
                    }
                }
            }
            
            // Default: return subtitle or empty
            return result.subtitle || '';
        },

        getHeaderLabel(result) {
             var parsed = this.parseDisplayText(result);
            if (this.isInvoiceResult(result)) {
                return this.$t ? this.$t('InvoiceNumber') : 'Invoice Number';
            }
            if (this.isBillingRuleResult(result)) {
                return this.$t ? this.$t('billing_rule_name') : 'Billing Rule';
            }
            if (this.isUserResult(result)) {
                return this.$t ? this.$t('email_id') : 'Email';
            }
            if (this.isUserResult(result)) {
                return this.$t ? this.$t('email_id') : 'Email';
            }
            if (this.isContractResult(result)) {
                if(parsed && parsed.contract_name!='') { 
                    return this.$t ? this.$t('contract_name') : 'Contract Name';
                }
                if(parsed && parsed.user_name !='') {    
                    return this.$t ? this.$t('user_name') : 'User Name';
                }
                return this.$t ? this.$t('email_id') : 'Email';
            }
            if (this.isCdcCodeResult(result)) {
                return this.$t ? this.$t('cdc_code') : 'CDC Code';
            }
            if (this.isUtilityResult(result)) {
                return this.$t ? this.$t('utility_name') : 'Utility Name';
            }
            if (this.isTicketResult(result)) {
                return this.$t ? this.$t('TicketNumber') : 'Ticket Number';
            }
           
        },

        getDescriptionLabel(result) {
            var parsed = this.parseDisplayText(result);
            if (this.isInvoiceResult(result)) {
                return this.$t ? this.$t('contract_name') : 'Contract Name';
            }
            if (this.isBillingRuleResult(result)) {
                return this.$t ? this.$t('contract_name') : 'Contract Name';
            }
            if (this.isUserResult(result)) {
                return this.$t ? this.$t('user_name') : 'User Name';
            }
            if (this.isContractResult(result)) {
                return this.$t ? this.$t('Email') : 'Email';
            }
            if (this.isCdcCodeResult(result)) {
                return this.$t ? this.$t('utility_name') : 'Utility Name';
            }
            if (this.isUtilityResult(result)) {
                debugger
               
                return this.$t ? this.$t('Utility_Desc') : 'Utility Description';
            }
            if (this.isTicketResult(result)) {
                return this.$t ? this.$t('ticket_subject') : 'ticket_subject';
            }
        },
        
        getStatusClass(status) {
            if (!status) return '';
            var statusLower = status.toString().toLowerCase().trim();
            
            // Active - Green
            if (statusLower === 'active') {
                return 'status-active';
            }
            // Inactive - Red
            else if (statusLower === 'inactive') {
                return 'status-inactive';
            }
            // Sent - Blue
            else if (statusLower === 'sent') {
                return 'status-sent';
            }
            // Cancelled - Red
            else if (statusLower === 'cancelled' || statusLower === 'canceled' || statusLower === 'cancel') {
                return 'status-cancelled';
            }
            // Generated - Yellow/Orange
            else if (statusLower === 'generated') {
                return 'status-generated';
            }
            // Released - Green
            else if (statusLower === 'released') {
                return 'status-released';
            }
            // Failed - Red
            else if (statusLower === 'failed') {
                return 'status-failed';
            }
            // Deleted - Dark Red
            else if (statusLower === 'deleted') {
                return 'status-deleted';
            }
            // UFW - Blue (Unpaid/Unfulfilled)
            else if (statusLower === 'ufw') {
                return 'status-sent';
            }
            // Default - Blue
            return 'status-default';
        },
        
        getEntityTypeFromModuleName(moduleName) {
            if (!moduleName) return null;
            var moduleLower = moduleName.toLowerCase().trim();
            switch (moduleLower) {
                case 'billing':
                    return 'Talygen_bill';
                case 'user':
                    return 'Talygen_user';    
                case 'contract':
                    return 'Talygen_company_client';
                case 'cdc_code':
                    return 'TALYGEN_BE_cdc_code_info';
                case 'utility':
                    return 'TALYGEN_client_additional_info';    
                case 'ticketing':
                    return 'TALYGEN_ticket';
                default:
                    return moduleName; // Return as-is if no mapping found
            }
        }
    },
    beforeDestroy() {
        var vm = this;
        if (vm.searchDebounceTimer) {
            clearTimeout(vm.searchDebounceTimer);
        }
    }
}
